select
id, job_code, job_name, company_id, jd_descriptions, jd_corereq, job_type, salary_range, city, status,
create_time, update_time
from jd_job


        and id = #{id}


        and job_code = #{jobCode}


        and job_name = #{jobName}


        and company_id = #{companyId}


        and jd_descriptions = #{jdDescriptions}


        and jd_corereq = #{jdCorereq}


        and job_type = #{jobType}


        and salary_range = #{salaryRange}


        and city = #{city}


        and status = #{status}


        and create_time = #{createTime}


        and update_time = #{updateTime}


limit #{pageable.offset}, #{pageable.pageSize}

